            for p in parts[:-1]:
                nx = cur.get(p)
                if not isinstance(nx, dict):
                    nx = dict()
                    cur[p] = nx
                cur = nx
            cur[parts[-1]] = vars[k]
    return out
def as_list(x):
    if isinstance(x, list):
        return x
