        try:
            y = json.loads(x)
            return y if isinstance(y, list) else []
        except Exception:
            return []
    if isinstance(x, dict):
        ks = sorted([k for k in x.keys() if str(k).isdigit()], key=lambda z: int(z))
        return [x[k] for k in ks]
    return []
